import randomdef parse_fasta(filepath):    """Reads a .fna file, ignores the header, and returns the raw DNA string."""    with open(filepath, 'r') as file:        return "".join(line.strip() for line in file.readlines()[1:]).upper()def get_overlap(left_read, right_read, min_overlap=30):    """Finds the longest suffix of 'left_read' that matches the prefix of 'right_read'."""    start = 0    while True:            start = left_read.find(right_read[:min_overlap], start)        if start == -1:            return 0 # No overlap found                if right_read.startswith(left_read[start:]):            return len(left_read) - start        start += 1def greedy_assembly(reads, min_overlap=30):    """Naively merges reads using the greedy overlap approach."""    pool = reads[:200].copy()         while len(pool) > 1:        max_overlap = 0        merge_left_idx, merge_right_idx = -1, -1                for i in range(len(pool)):            for j in range(len(pool)):                if i != j:                    overlap = get_overlap(pool[i], pool[j], min_overlap)                    if overlap > max_overlap:                        max_overlap, merge_left_idx, merge_right_idx = overlap, i, j          if max_overlap == 0:            break                         left = pool[merge_left_idx]        right = pool[merge_right_idx]        merged_read = left + right[max_overlap:]                pool.pop(max(merge_left_idx, merge_right_idx))        pool.pop(min(merge_left_idx, merge_right_idx))        pool.append(merged_read)                print(f"Merged two reads (Overlap: {max_overlap} bp). Remaining pool: {len(pool)} fragments.")            return poolprint("Loading hepatitis.fna...")genome = parse_fasta("hepatitis.fna")print(f"Loaded HBV Genome: {len(genome)} bp")print("\nExtracting 2,000 random reads (100-120 bp)...")reads = []for _ in range(2000):    length = random.randint(100, 120)    start_idx = random.randint(0, len(genome) - length)    reads.append(genome[start_idx : start_idx + length])print("\nStarting Greedy Assembly (subset of 200 reads to prevent CPU lock)...")contigs = greedy_assembly(reads, min_overlap=30)print("\n--- ASSEMBLY RESULTS ---")print(f"The algorithm halted and produced {len(contigs)} disconnected fragments (contigs).")